-- Thermo Scientific Eutech 1700 Series bench meters: 1710 pH/mV, 1720 conductivity, 1730 dissolved oxygen
-- (9 meter/kit configurations) plus 3 accessories with photos. 12 products in total.
-- From the Eutech 1700 Series brochure. Photos: public/products/eutech/. Brand: Eutech Instruments.
-- Run in Supabase -> SQL Editor (choose "Run without RLS" if asked). Safe to run again: products are updated by SKU (= cat. no.).
alter table products add column if not exists features jsonb not null default '[]'::jsonb;
insert into brands (name, slug, website_url) values ('Eutech Instruments', 'eutech-instruments', 'https://www.eutechinst.com/')
on conflict (slug) do update set name = excluded.name, website_url = coalesce(brands.website_url, excluded.website_url);
insert into categories (name, slug, sort_order) values ('Environmental Equipment', 'environmental-equipment', 6) on conflict (slug) do nothing;

insert into products (sku, name, slug, description, specs, features, category_id, brand_id, image_url, is_active)
select v.sku, v.name, v.slug, v.description, v.specs::jsonb, v.features::jsonb, c.id, b.id, v.image_url, true
from (values
  ('EBPH171000', 'Eutech 1710 pH/mV Bench Meter – Meter with Stand', 'eutech-1710-ph-mv-bench-meter-meter-with-stand-ebph171000', 'The Thermo Scientific Eutech 1710 is a pH / mV / temperature bench meter for pH and redox measurements from the Eutech 1700 Series. This configuration (cat. no. EBPH171000) comes with: stand, PC cable and 100 to 240 V universal power adapter. 3-year warranty against manufacturing defects.', '[["Cat. no.", "EBPH171000"], ["Series", "Eutech 1700 Series bench meter"], ["Parameters", "pH / mV / temperature"], ["Supplied with", "Stand, PC cable and 100 to 240 V universal power adapter"], ["pH range", "-2.00 to 18.00 pH"], ["pH resolution", "0.1 / 0.01 pH"], ["pH accuracy", "±0.01 pH ±1 LSD"], ["pH calibration", "1 to 5 points"], ["Automatic buffer sets", "USA (1.68, 4.01, 7.00, 10.01, 12.45); NIST (1.68, 4.01, 6.86, 9.18, 12.45)"], ["mV / RmV range", "±2000.0 mV"], ["mV resolution", "0.1 mV"], ["mV accuracy", "±0.2 mV or ±0.05 % of reading, whichever is greater"], ["RmV calibration", "1 point"], ["Calibration method", "Automatic buffer recognition with manual buffer entry option"], ["Slope display", "Yes"], ["mV offset adjustment", "Up to ±250 mV"], ["Temperature range", "-5.0 to 105.0 °C"], ["Temperature resolution", "0.1 °C"], ["Temperature accuracy", "±0.3 °C"], ["Temperature input", "Manual or automatic with ATC probe"], ["Temperature calibration", "1 point, ±5.0 °C"], ["Temperature offset adjustment", "Up to ±5 °C"], ["Display", "5 in. segmented LCD with backlight"], ["Date and time", "Yes"], ["Read types", "Continuous, auto-read, timed"], ["Data log", "Up to 500 points"], ["Calibration log", "pH, RmV and temperature"], ["Data output", "Computer or printer"], ["Calibration due alarm", "1 to 168 hours or off"], ["Alarms", "Visual and on/off audible"], ["Memory", "Non-volatile"], ["Power", "100 to 240 V universal power adapter"], ["Warranty", "3 years"], ["Timed read interval", "5 seconds to 60 minutes"], ["Date format", "DD-MM-YYYY or MM-DD-YYYY (selectable); 12-hour time"], ["Sleep mode", "Yes, optional"], ["Self-test", "Automatic at start-up"], ["Inputs", "BNC, ATC"], ["Data output format", "CSV or print"], ["Enclosure", "IP54"], ["Certifications", "CE, cTUVus, FCC Class B, CES-001, KC, RCM"], ["Power supply", "100 to 240 VAC, 50/60 Hz; 9 V DC adapter, 1.3 A"], ["Dimensions (L × W × H)", "198.3 × 155.2 × 61.7 mm"], ["Weight", "700 g"], ["Operating conditions", "Indoors, 5 to 45 °C, 5 to 85 % RH non-condensing, up to 2,000 m altitude"], ["Storage conditions", "-20 to 60 °C, 5 to 85 % RH non-condensing"]]', '["Easy to use and easy to calibrate: ideal for routine, economical pH testing", "Reads pH, mV and temperature at the same time", "One- to five-point pH calibration with automatic buffer recognition or manual entry", "One-point relative mV (RmV) calibration", "Electrode condition icon shows pH electrode status", "Large, bright backlit display for easy reading", "Small footprint saves bench space", "500-point data log, exported to a computer or printer", "Non-volatile memory keeps settings and data if the power fails", "On-screen stability icons", "Automatic or manual temperature compensation; one-point ATC probe offset calibration", "Meter-attached electrode stand", "Data and calibration logs are date and time stamped for GLP/GMP"]', 'environmental-equipment', '/products/eutech/1710-meter.jpg'),
  ('EBPH171001', 'Eutech 1710 pH/mV Bench Meter – Kit with Gel-filled pH/ATC Electrode', 'eutech-1710-ph-mv-bench-meter-kit-with-gel-filled-ph-atc-electrode-ebph171001', 'The Thermo Scientific Eutech 1710 is a pH / mV / temperature bench meter for pH and redox measurements from the Eutech 1700 Series. This configuration (cat. no. EBPH171001) comes with: gel-filled plastic-body pH/ATC electrode, solutions, stand, PC cable and power adapter. 3-year warranty against manufacturing defects.', '[["Cat. no.", "EBPH171001"], ["Series", "Eutech 1700 Series bench meter"], ["Parameters", "pH / mV / temperature"], ["Supplied with", "Gel-filled plastic-body pH/ATC electrode, solutions, stand, PC cable and power adapter"], ["pH range", "-2.00 to 18.00 pH"], ["pH resolution", "0.1 / 0.01 pH"], ["pH accuracy", "±0.01 pH ±1 LSD"], ["pH calibration", "1 to 5 points"], ["Automatic buffer sets", "USA (1.68, 4.01, 7.00, 10.01, 12.45); NIST (1.68, 4.01, 6.86, 9.18, 12.45)"], ["mV / RmV range", "±2000.0 mV"], ["mV resolution", "0.1 mV"], ["mV accuracy", "±0.2 mV or ±0.05 % of reading, whichever is greater"], ["RmV calibration", "1 point"], ["Calibration method", "Automatic buffer recognition with manual buffer entry option"], ["Slope display", "Yes"], ["mV offset adjustment", "Up to ±250 mV"], ["Temperature range", "-5.0 to 105.0 °C"], ["Temperature resolution", "0.1 °C"], ["Temperature accuracy", "±0.3 °C"], ["Temperature input", "Manual or automatic with ATC probe"], ["Temperature calibration", "1 point, ±5.0 °C"], ["Temperature offset adjustment", "Up to ±5 °C"], ["Display", "5 in. segmented LCD with backlight"], ["Date and time", "Yes"], ["Read types", "Continuous, auto-read, timed"], ["Data log", "Up to 500 points"], ["Calibration log", "pH, RmV and temperature"], ["Data output", "Computer or printer"], ["Calibration due alarm", "1 to 168 hours or off"], ["Alarms", "Visual and on/off audible"], ["Memory", "Non-volatile"], ["Power", "100 to 240 V universal power adapter"], ["Warranty"