  ('EBEC172000', 'Eutech 1720 Conductivity Bench Meter – Meter with Stand', 'eutech-1720-conductivity-bench-meter-meter-with-stand-ebec172000', 'The Thermo Scientific Eutech 1720 is a conductivity / salinity / TDS / temperature bench meter from the Eutech 1700 Series. This configuration (cat. no. EBEC172000) comes with: stand, PC cable and 100 to 240 V universal power adapter. 3-year warranty against manufacturing defects.', '[["Cat. no.", "EBEC172000"], ["Series", "Eutech 1700 Series bench meter"], ["Parameters", "conductivity / TDS / salinity / temperature"], ["Supplied with", "Stand, PC cable and 100 to 240 V universal power adapter"], ["Conductivity range", "0.00 µS to 500.0 mS"], ["Conductivity resolution", "0.01, 0.1, 1 µS; 0.01, 0.1 mS"], ["Conductivity accuracy", "±0.5 % of reading ±1 LSD"], ["Conductivity calibration", "1 to 5 points"], ["Temperature compensation", "Linear (0 to 10 %/°C) or off"], ["Normalisation temperature", "15, 20, 25 or 30 °C"], ["TDS range", "0.00 ppm to 500.0 ppt (TDS factor 1.00)"], ["TDS resolution", "0.01, 0.1, 1 ppm; 0.01, 0.1 ppt"], ["TDS accuracy", "±0.5 % of reading ±1 LSD"], ["TDS calibration", "1 to 5 points"], ["TDS factor", "0.40 to 1.00"], ["Salinity range", "0.00 to 80.0 ppt"], ["Salinity resolution", "0.01, 0.1 ppt"], ["Salinity accuracy", "±0.5 % of reading ±1 LSD"], ["Salinity calibration", "1 point"], ["Temperature range", "-5.0 to 105.0 °C"], ["Temperature resolution", "0.1 °C"], ["Temperature accuracy", "±0.3 °C"], ["Temperature input", "Manual or automatic with ATC probe"], ["Temperature calibration", "1 point, ±5.0 °C"], ["Display", "5 in. segmented LCD with backlight"], ["Date and time", "Yes"], ["Read types", "Continuous, auto-read, timed"], ["Data log", "Up to 500 points"], ["Calibration log", "Conductivity, TDS, salinity and temperature"], ["Data output", "Computer or printer"], ["Calibration due alarm", "1 to 168 hours or off"], ["Alarms", "Visual and on/off audible"], ["Memory", "Non-volatile"], ["Power", "